import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%A4%E3%83%B3%E3%83%89%E3%83%8D%E3%82%B7%E3%82%A2%E8%AA%9E.html","title":"インドネシア語","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.58,"words":175},"filePathRelative":"インドネシア語.md"}`),a={name:`インドネシア語.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="インドネシア語" tabindex="-1"><a class="header-anchor" href="#インドネシア語"><span>インドネシア語</span></a></h1><ul><li><a href="https://www.kiriusa.com/indonesian-exam-c/" target="_blank" rel="noopener noreferrer">インドネシア語検定Ｃ級　合格体験記 - うさぎメモ＠多言語に夢中</a> 参考書の感想がいろいろ載っていて参考になる。</li><li><a href="./ニューエクスプレスインドネシア語.html">ニューエクスプレスインドネシア語</a></li><li><a href="./インドネシア語のしくみ.html">インドネシア語のしくみ</a></li></ul><h2 id="インドネシア語の基本が7日間でわかる本" tabindex="-1"><a class="header-anchor" href="#インドネシア語の基本が7日間でわかる本"><span>インドネシア語の基本が7日間でわかる本</span></a></h2><p><a href="https://www.amazon.co.jp/dp/4046045876?&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=7369ae300e7babb2e3c71f640724bd74&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: インドネシア語の基本が7日間でわかる本 </a></p><p>Kindle Unlimited対象だったので試しに見ている。結構良さそうなので買ってもいいかもしれん。</p><h2 id="ことたびインドネシア語" tabindex="-1"><a class="header-anchor" href="#ことたびインドネシア語"><span>ことたびインドネシア語</span></a></h2><p><a href="https://www.amazon.co.jp/dp/4560005672?&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=7c25b9f6c6a8101f6075c557f5e7be95&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: インドネシア語: ことばをもって旅に出よう! (ことたび) </a></p><p>2010年くらいにインドネシア回った時に使った本。 旅行会話集的なものと構文ごとの整理みたいなのが半々になってるような本。</p><p>基本的に短文。シーンごとに分かりやすい分、別のシーンで同じ構文がでてくる所もあるので効率は悪いか。 音声がついているので良く聞いていた。</p><h2 id="アジア語楽紀行-バリ・旅するインドネシア語" tabindex="-1"><a class="header-anchor" href="#アジア語楽紀行-バリ・旅するインドネシア語"><span>アジア語楽紀行 バリ・旅するインドネシア語</span></a></h2><p><a href="https://www.amazon.co.jp/dp/4141892688?&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=e8955fc42b2aaac93eb5c662c8fbec1e&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: アジア語楽紀行 バリ・旅するインドネシア語</a></p><p>2010年くらいにインドネシア回った時に使った本。NHKのテレビ番組のテキストだと思うが、たぶんブックオフで安かったとかで買ったんだと思う。</p><p>音声は（本だけだと）無いが、旅行で遭遇するシチュエーションごとに構文と単語入れ替えでなんとかする系の会話本。 音声があればなぁ。</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};